(function executeProducerScript(current, producer) {
    // Set status to 'new' for newly created tyre requests
    current.status = 'new';

    // Set the current user context on the record
    current.sys_created_by = gs.getUserName();

    // Do NOT call current.update() or current.insert() here
})(current, producer);
